using MAKH.Application.Administration;
using MAKH.Application.Security;
using MAKH.Infrastructure.Administration;
using Xunit;

namespace MAKH.Architecture.Tests;

public sealed class AdministrationServiceTests
{
    private static readonly DateTimeOffset Now = new(2026, 8, 13, 16, 0, 0, TimeSpan.Zero);
    private readonly AdministrationService service = new(new InMemoryAdministrationStore());

    [Fact] public void OperationsCanPublishProviderReference() => Assert.Equal(1, service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish), Now).Sequence);
    [Fact] public void OperationsCannotPublishRiskPolicy() => Assert.Throws<UnauthorizedAccessException>(() => service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.RiskPolicy, AdministrativeAction.Publish), Now));
    [Fact] public void RiskAdministratorCanPublishRiskPolicy() => Assert.Equal(1, service.Execute(Context(PlatformRoles.RiskAdministrator), Command(AdministrativeResource.RiskPolicy, AdministrativeAction.Publish), Now).Sequence);
    [Fact] public void RiskAdministratorCannotChangeProvider() => Assert.Throws<UnauthorizedAccessException>(() => service.Execute(Context(PlatformRoles.RiskAdministrator), Command(AdministrativeResource.Provider, AdministrativeAction.Publish), Now));
    [Fact] public void AuditorCannotMutate() => Assert.Throws<UnauthorizedAccessException>(() => service.Execute(Context(PlatformRoles.Auditor), Command(AdministrativeResource.MarketCalendar, AdministrativeAction.Publish), Now));
    [Fact] public void AuditorCanRunDiagnostic() => Assert.Equal(AdministrativeAction.RunDiagnostic, service.Execute(Context(PlatformRoles.Auditor), Command(AdministrativeResource.Diagnostics, AdministrativeAction.RunDiagnostic), Now).Action);
    [Fact] public void UnknownRoleDenied() => Assert.Throws<UnauthorizedAccessException>(() => service.Execute(Context("Trader"), Command(AdministrativeResource.Diagnostics, AdministrativeAction.RunDiagnostic), Now));
    [Fact] public void StaleMfaDenied() => Assert.Throws<UnauthorizedAccessException>(() => service.Execute(Context("OperationsAdministrator", false), Command(AdministrativeResource.Provider, AdministrativeAction.Publish), Now));
    [Fact] public void ExpiredElevationDenied() => Assert.Throws<UnauthorizedAccessException>(() => service.Execute(new(Guid.NewGuid(), "OperationsAdministrator", true, Now.AddHours(-2), Now.AddHours(-1), "approved change", "corr"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish), Now));
    [Fact] public void ElevationOverOneHourRejected() => Assert.Throws<ArgumentException>(() => new AdministrativeContext(Guid.NewGuid(), "OperationsAdministrator", true, Now, Now.AddHours(2), "approved", "corr"));
    [Fact] public void VersionConflictRejected() { service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish), Now); Assert.Throws<InvalidOperationException>(() => service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish, "none", Guid.NewGuid()), Now)); }
    [Fact] public void ExactCommandReplayIsIdempotent() { var command = Command(AdministrativeResource.Provider, AdministrativeAction.Publish); var context = Context("OperationsAdministrator"); var first = service.Execute(context, command, Now); var replay = service.Execute(context, command, Now.AddMinutes(1)); Assert.Equal(first, replay); Assert.Single(service.Audit()); }
    [Fact] public void ChangedCommandIdentityConflicts() { var id = Guid.NewGuid(); service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish, commandId: id), Now); Assert.Throws<InvalidOperationException>(() => service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.MarketCalendar, AdministrativeAction.Publish, commandId: id), Now)); }
    [Fact] public void ChangedExpectedVersionWithSameCommandIdConflicts() { var id = Guid.NewGuid(); var context = Context("OperationsAdministrator"); service.Execute(context, Command(AdministrativeResource.Provider, AdministrativeAction.Publish, commandId: id), Now); Assert.Throws<InvalidOperationException>(() => service.Execute(context, Command(AdministrativeResource.Provider, AdministrativeAction.Publish, expected: "v0", commandId: id), Now)); }
    [Fact] public void ChangedProposedVersionWithSameCommandIdConflicts() { var id = Guid.NewGuid(); var context = Context("OperationsAdministrator"); service.Execute(context, Command(AdministrativeResource.Provider, AdministrativeAction.Publish, commandId: id), Now); Assert.Throws<InvalidOperationException>(() => service.Execute(context, new AdministrativeCommand(id, AdministrativeResource.Provider, AdministrativeAction.Publish, "resource-1", "none", "v2", "safe configuration reference"), Now)); }
    [Fact] public void ChangedSummaryWithSameCommandIdConflicts() { var id = Guid.NewGuid(); var context = Context("OperationsAdministrator"); service.Execute(context, Command(AdministrativeResource.Provider, AdministrativeAction.Publish, commandId: id), Now); Assert.Throws<InvalidOperationException>(() => service.Execute(context, new AdministrativeCommand(id, AdministrativeResource.Provider, AdministrativeAction.Publish, "resource-1", "none", "v1", "different safe reference"), Now)); }
    [Fact] public void DifferentActorCannotReplayPrivilegedCommand() { var id = Guid.NewGuid(); service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish, commandId: id), Now); Assert.Throws<InvalidOperationException>(() => service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish, commandId: id), Now)); }
    [Fact] public void AuditHasBeforeAfterHashesAndReason() { var result = service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish), Now); Assert.Equal(64, result.BeforeSha256.Length); Assert.Equal(64, result.AfterSha256.Length); Assert.NotEqual(result.BeforeSha256, result.AfterSha256); Assert.Equal("approved change", result.Reason); }
    [Fact] public void CredentialMaterialRejected() => Assert.Throws<ArgumentException>(() => new AdministrativeCommand(Guid.NewGuid(), AdministrativeResource.Provider, AdministrativeAction.Publish, "provider", "none", "v1", "api token value"));
    [Fact] public void ProviderCredentialSummaryRejected() => Assert.Throws<ArgumentException>(() => service.Execute(Context("OperationsAdministrator"), new(Guid.NewGuid(), AdministrativeResource.Provider, AdministrativeAction.Publish, "provider", "none", "v1", "credential reference"), Now));
    [Fact] public void ResultHasNoTradingOrCredentialAuthority() { var result = service.Execute(Context("OperationsAdministrator"), Command(AdministrativeResource.Provider, AdministrativeAction.Publish), Now); Assert.False(result.CreatesTradingAuthority); Assert.False(result.ContainsCredentials); }
    [Fact] public void UndefinedResourceAndActionFailAtCommandBoundary() { Assert.Throws<ArgumentOutOfRangeException>(() => Command((AdministrativeResource)99, AdministrativeAction.Publish)); Assert.Throws<ArgumentOutOfRangeException>(() => Command(AdministrativeResource.Provider, (AdministrativeAction)99)); }
    [Fact] public void NonUtcElevationFailsAtContextBoundary() => Assert.Throws<ArgumentException>(() => new AdministrativeContext(Guid.NewGuid(), "OperationsAdministrator", true, Now.ToOffset(TimeSpan.FromHours(1)), Now.AddMinutes(30).ToOffset(TimeSpan.FromHours(1)), "approved", "corr"));
    [Fact] public void ControlCharactersFailAcrossContextAndCommandEvidence() { Assert.Throws<ArgumentException>(() => new AdministrativeContext(Guid.NewGuid(), "OperationsAdministrator", true, Now, Now.AddMinutes(30), "approved\nforged", "corr")); Assert.Throws<ArgumentException>(() => new AdministrativeCommand(Guid.NewGuid(), AdministrativeResource.Provider, AdministrativeAction.Publish, "provider", "none", "v1", "safe\r\nforged")); }
    [Fact] public void AddressMaterialFailsAcrossContextEvidence() => Assert.Throws<ArgumentException>(() => new AdministrativeContext(Guid.NewGuid(), "admin@example.com", true, Now, Now.AddMinutes(30), "approved", "corr"));

    private static AdministrativeContext Context(string role, bool mfa = true) => new(Guid.NewGuid(), role, mfa, Now.AddMinutes(-5), Now.AddMinutes(55), "approved change", "corr-1");
    private static AdministrativeCommand Command(AdministrativeResource resource, AdministrativeAction action, string expected = "none", Guid? commandId = null) => new(commandId ?? Guid.NewGuid(), resource, action, "resource-1", expected, "v1", "safe configuration reference");
}
